pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 v) internal {
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        try c.SetMinSum(v) {} catch { return; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        assertTrue(minAfter == v && (v == minBefore || minBefore == 0));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
